UPDATE doc_schedule_record
SET status = 1,reason = #{reason}



                doc_id IN

                 #{docId}





            AND schedule_date BETWEEN #{startDate} AND #{endDate}



            AND (schedule_date > #{startDate}
            OR (schedule_date = #{startDate} AND CAST(SUBSTRING(template_id FROM '[0-9]+') AS INTEGER) >=
            CAST(SUBSTRING(#{startTemplate} FROM '[0-9]+') AS INTEGER)))




            AND (schedule_date < #{endDate}
            OR (schedule_date = #{endDate} AND CAST(SUBSTRING(template_id FROM '[0-9]+') AS INTEGER) <=
            CAST(SUBSTRING(#{endTemplate} FROM '[0-9]+') AS INTEGER)))

UPDATE doc_schedule_record
SET reason = #{reason},
schedule_date = schedule_date + INTERVAL '1' DAY * #{delay_days}



        doc_id IN

            #{docId}



        AND schedule_date BETWEEN #{startDate} AND #{endDate}



        AND (schedule_date > #{startDate}
        OR (schedule_date = #{startDate} AND CAST(SUBSTRING(template_id FROM '[0-9]+') AS INTEGER) >=
        CAST(SUBSTRING(#{startTemplate} FROM '[0-9]+') AS INTEGER)))




        AND (schedule_date < #{endDate}
        OR (schedule_date = #{endDate} AND CAST(SUBSTRING(template_id FROM '[0-9]+') AS INTEGER) <=
        CAST(SUBSTRING(#{endTemplate} FROM '[0-9]+') AS INTEGER)))
